-- ============================================
-- LUMA — Thème 16 : LONG 3/3 x4 — Valider son visa working holiday via le travail régional
-- ============================================


update scenarios set content = '{"characters": {"agent_visa": "l''agent des visas", "farmer": "le fermier"}, "start_node": "n1", "nodes": {"n1": {"speaker": "agent_visa", "text": "So, to qualify for your second-year visa, you need 88 days of specified regional work.", "text_fr": "Donc, pour être éligible à votre visa de deuxième année, vous avez besoin de 88 jours de travail régional spécifié.", "choices": [{"text": "What exactly counts as specified regional work?", "text_fr": "Qu''est-ce qui compte exactement comme travail régional spécifié ?", "next": "n2"}, {"text": "I''ve heard farm work counts — is that my best option?", "text_fr": "J''ai entendu dire que le travail agricole compte — c''est ma meilleure option ?", "next": "n2b"}]}, "n2": {"speaker": "agent_visa", "text": "Mainly agriculture, but also mining, construction, or fishing in eligible postcodes.", "text_fr": "Principalement l''agriculture, mais aussi les mines, la construction, ou la pêche dans des codes postaux éligibles.", "choices": [{"text": "Agriculture sounds most accessible for someone with my background.", "text_fr": "L''agriculture semble la plus accessible pour quelqu''un avec mon parcours.", "next": "n3"}]}, "n2b": {"speaker": "agent_visa", "text": "It''s definitely popular, and usually easiest to find without specific skills.", "text_fr": "C''est définitivement populaire, et généralement le plus facile à trouver sans compétences spécifiques.", "choices": [{"text": "That''s reassuring, I don''t have specialized experience yet.", "text_fr": "Ça rassure, j''ai pas encore d''expérience spécialisée.", "next": "n3"}]}, "n3": {"speaker": "you_thought", "text": "(You find a fruit farm hiring pickers and apply immediately.)", "text_fr": "(Vous trouvez une ferme fruitière qui embauche des cueilleurs et postulez immédiatement.)", "choices": [{"text": "(Start the work, tracking each day carefully for visa purposes.)", "text_fr": "(Commence le travail, en suivant soigneusement chaque jour pour le visa.)", "next": "n4"}]}, "n4": {"speaker": "farmer", "text": "Welcome! Just so you know, we''ll sign off on your regional work days properly.", "text_fr": "Bienvenue ! Sachez juste qu''on va bien signer vos jours de travail régional.", "choices": [{"text": "Thank you, that''s exactly what I need for my visa application.", "text_fr": "Merci, c''est exactement ce dont j''ai besoin pour ma demande de visa.", "next": "n5"}]}, "n5": {"speaker": "you_thought", "text": "(Weeks pass, and you diligently track each qualifying workday.)", "text_fr": "(Des semaines passent, et vous suivez consciencieusement chaque jour de travail qualifiant.)", "choices": [{"text": "(Check your progress after one month of work.)", "text_fr": "(Vérifie ta progression après un mois de travail.)", "next": "n6"}]}, "n6": {"speaker": "farmer", "text": "You''re at day 45 now, more than halfway to your goal!", "text_fr": "Vous êtes au jour 45 maintenant, plus de la moitié de votre objectif !", "choices": [{"text": "That''s such a relief to hear, I was worried about the pace.", "text_fr": "Ça soulage tellement d''entendre ça, j''avais peur du rythme.", "next": "n7"}]}, "n7": {"speaker": "you_thought", "text": "(A minor setback: you fall ill for a week, worried about losing progress.)", "text_fr": "(Un petit revers : vous tombez malade pendant une semaine, inquiet de perdre votre progression.)", "choices": [{"text": "(Rest and recover, reassured that a week won''t derail the overall goal.)", "text_fr": "(Repose-toi et récupère, rassuré qu''une semaine ne fera pas dérailler l''objectif global.)", "next": "n8"}]}, "n8": {"speaker": "farmer", "text": "Take the time you need to recover, your health matters more than the timeline.", "text_fr": "Prenez le temps dont vous avez besoin pour récupérer, votre santé compte plus que le calendrier.", "choices": [{"text": "Thank you for understanding, I''ll be back as soon as I''m better.", "text_fr": "Merci de comprendre, je serai de retour dès que j''irai mieux.", "next": "n9"}]}, "n9": {"speaker": "you_thought", "text": "(Recovered and back at work, you push through the final stretch with renewed energy.)", "text_fr": "(Rétabli et de retour au travail, vous poussez à travers la dernière ligne droite avec une énergie renouvelée.)", "choices": [{"text": "(Count down the final days with growing excitement.)", "text_fr": "(Compte les derniers jours avec une excitation grandissante.)", "next": "n10"}]}, "n10": {"speaker": "farmer", "text": "Day 88! Congratulations, you''ve officially completed your regional work requirement.", "text_fr": "Jour 88 ! Félicitations, vous avez officiellement complété votre exigence de travail régional.", "choices": [{"text": "I honestly can''t believe I made it, this means so much.", "text_fr": "J''arrive honnêtement pas à croire que j''y sois arrivé, ça compte tellement.", "next": "n11"}]}, "n11": {"speaker": "farmer", "text": "You earned every bit of it. I''ll get your paperwork signed off today.", "text_fr": "Vous l''avez mérité entièrement. Je vais faire signer vos papiers aujourd''hui.", "choices": [{"text": "Thank you so much for everything, this whole experience has been incredible.", "text_fr": "Merci beaucoup pour tout, toute cette expérience a été incroyable.", "next": "n12"}]}, "n12": {"speaker": "agent_visa", "text": "(Later) Congratulations, your second-year visa application has been approved!", "text_fr": "(Plus tard) Félicitations, votre demande de visa deuxième année a été approuvée !", "choices": [{"text": "That''s the best news I''ve heard in months. Thank you for all your help.", "text_fr": "C''est la meilleure nouvelle que j''aie entendue depuis des mois. Merci pour toute votre aide.", "next": "end_visa"}]}, "end_visa": {"speaker": "agent_visa", "text": "Congratulations again, enjoy your second year in Australia!", "text_fr": "Encore félicitations, profitez de votre deuxième année en Australie !", "end": true, "ending_label": "Visa deuxième année validé avec succès 🎉🇦🇺📋"}}}'::jsonb, is_playable = true
where title = 'Valider son visa working holiday via le travail régional'
  and theme_id = (select id from scenario_themes where position = 16 and language_id = (select id from languages where code = 'en'));
